'use client';

import React, { useState, useEffect } from 'react';
import { DataStore } from '@/lib/store/data-store';
import { useStore } from '@/lib/context/StoreContext';
import { cn, formatDate } from '@/lib/utils';
import { Review, Product } from '@/types';
import { Star, Check, X, Trash2, ChevronDown } from 'lucide-react';

export default function ReviewsManagementPage() {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [products, setProducts] = useState<Record<string, Product>>({});
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'pending' | 'approved' | 'rejected'>('all');
  const [selectedReviewIds, setSelectedReviewIds] = useState<Set<string>>(new Set());
  const [expandedReviewId, setExpandedReviewId] = useState<string | null>(null);

  const { refreshData } = useStore();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    setLoading(true);
    const allReviews = DataStore.getReviews();
    allReviews.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
    setReviews(allReviews);

    const prods = DataStore.getProducts();
    const prodMap: Record<string, Product> = {};
    prods.forEach(p => prodMap[p.id] = p);
    setProducts(prodMap);

    setLoading(false);
  };

  const handleUpdateStatus = (id: string, status: 'approved' | 'rejected') => {
    DataStore.updateReviewStatus(id, status);
    refreshData();
    loadData();
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Are you sure you want to delete this review?')) {
      DataStore.deleteReview(id);
      refreshData();
      loadData();
    }
  };

  const handleBulkAction = (action: 'approved' | 'rejected') => {
    if (selectedReviewIds.size === 0) return;
    selectedReviewIds.forEach(id => {
      DataStore.updateReviewStatus(id, action);
    });
    setSelectedReviewIds(new Set());
    refreshData();
    loadData();
  };

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedReviewIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedReviewIds(newSet);
  };

  const selectAll = (filtered: Review[]) => {
    if (selectedReviewIds.size === filtered.length) {
      setSelectedReviewIds(new Set());
    } else {
      setSelectedReviewIds(new Set(filtered.map(r => r.id)));
    }
  };

  const filteredReviews = reviews.filter(r => filter === 'all' || r.status === filter);

  const tabs = [
    { label: 'All Reviews', value: 'all' },
    { label: 'Pending', value: 'pending' },
    { label: 'Approved', value: 'approved' },
    { label: 'Rejected', value: 'rejected' },
  ] as const;

  const renderStars = (rating: number) => {
    return (
      <div className="flex text-amber-400">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star key={star} className={cn("h-3.5 w-3.5", star <= rating ? "fill-current" : "text-neutral-300 dark:text-neutral-700")} />
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100">Reviews & Moderation</h1>
          <p className="text-sm text-neutral-500 dark:text-neutral-400">Review, verify, and moderate patron testimonials.</p>
        </div>
      </div>

      <div className="bg-white dark:bg-[#14151a] rounded-xl border border-neutral-200 dark:border-neutral-800 shadow-sm overflow-hidden">
        <div className="p-4 border-b border-neutral-200 dark:border-neutral-800 flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="flex space-x-1">
            {tabs.map((tab) => (
              <button
                key={tab.value}
                onClick={() => setFilter(tab.value)}
                className={cn(
                  'px-3.5 py-1.5 text-xs font-semibold rounded-lg transition-colors',
                  filter === tab.value
                    ? 'bg-brand-amber/15 text-brand-amber'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800'
                )}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {selectedReviewIds.size > 0 && (
            <div className="flex space-x-2 animate-in fade-in">
              <span className="px-3 py-1.5 text-xs text-neutral-500 dark:text-neutral-400">{selectedReviewIds.size} selected</span>
              <button
                onClick={() => handleBulkAction('approved')}
                className="px-3 py-1.5 text-xs font-semibold bg-emerald-100 text-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300 rounded-lg hover:bg-emerald-200 transition-colors flex items-center"
              >
                <Check className="w-3.5 h-3.5 mr-1" /> Approve All
              </button>
              <button
                onClick={() => handleBulkAction('rejected')}
                className="px-3 py-1.5 text-xs font-semibold bg-red-100 text-red-800 dark:bg-red-950/40 dark:text-red-300 rounded-lg hover:bg-red-200 transition-colors flex items-center"
              >
                <X className="w-3.5 h-3.5 mr-1" /> Reject All
              </button>
            </div>
          )}
        </div>

        {loading ? (
          <div className="p-8 space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="h-16 bg-neutral-100 dark:bg-neutral-800 rounded animate-pulse" />
            ))}
          </div>
        ) : filteredReviews.length === 0 ? (
          <div className="p-12 text-center text-neutral-500 dark:text-neutral-400 text-sm">
            No reviews found matching the current filter.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs whitespace-nowrap">
              <thead className="bg-neutral-50 dark:bg-neutral-900 border-b border-neutral-200 dark:border-neutral-800">
                <tr>
                  <th className="px-4 py-3">
                    <input 
                      type="checkbox" 
                      className="rounded text-brand-amber focus:ring-brand-amber accent-brand-amber"
                      checked={selectedReviewIds.size > 0 && selectedReviewIds.size === filteredReviews.length}
                      onChange={() => selectAll(filteredReviews)}
                    />
                  </th>
                  <th className="px-5 py-3 font-medium text-neutral-900 dark:text-neutral-100">Product</th>
                  <th className="px-5 py-3 font-medium text-neutral-900 dark:text-neutral-100">Customer</th>
                  <th className="px-5 py-3 font-medium text-neutral-900 dark:text-neutral-100">Rating</th>
                  <th className="px-5 py-3 font-medium text-neutral-900 dark:text-neutral-100">Status</th>
                  <th className="px-5 py-3 font-medium text-neutral-900 dark:text-neutral-100">Date</th>
                  <th className="px-5 py-3 font-medium text-neutral-900 dark:text-neutral-100 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800">
                {filteredReviews.map((review) => {
                  const prod = products[review.product_id];
                  const prodImage = prod?.images?.[0]?.image_url || '/placeholder.jpg';

                  return (
                    <React.Fragment key={review.id}>
                      <tr className="hover:bg-neutral-50 dark:hover:bg-neutral-900/50 transition-colors group">
                        <td className="px-4 py-3.5">
                          <input 
                            type="checkbox" 
                            className="rounded text-brand-amber focus:ring-brand-amber accent-brand-amber"
                            checked={selectedReviewIds.has(review.id)}
                            onChange={() => toggleSelection(review.id)}
                          />
                        </td>
                        <td className="px-5 py-3.5">
                          <div className="flex items-center space-x-3 w-52 truncate">
                            {prod ? (
                              <>
                                <img src={prodImage} alt="" className="w-8 h-8 rounded object-cover border border-neutral-200 dark:border-neutral-700" />
                                <span className="font-medium text-neutral-900 dark:text-neutral-100 truncate" title={prod.title}>
                                  {prod.title}
                                </span>
                              </>
                            ) : (
                              <span className="text-neutral-400 italic">Piece archived</span>
                            )}
                          </div>
                        </td>
                        <td className="px-5 py-3.5">
                          <div className="font-medium text-neutral-900 dark:text-neutral-100">{review.user_name}</div>
                          {review.is_verified_purchase && <span className="text-[10px] text-emerald-600 dark:text-emerald-400 font-semibold">Verified Patron</span>}
                        </td>
                        <td className="px-5 py-3.5">
                          {renderStars(review.rating)}
                        </td>
                        <td className="px-5 py-3.5">
                          <span className={cn(
                            "px-2.5 py-0.5 rounded-full text-[11px] font-semibold capitalize",
                            review.status === 'approved' ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300" :
                            review.status === 'rejected' ? "bg-red-100 text-red-800 dark:bg-red-950/40 dark:text-red-300" :
                            "bg-amber-100 text-amber-800 dark:bg-amber-950/40 dark:text-amber-300"
                          )}>
                            {review.status}
                          </span>
                        </td>
                        <td className="px-5 py-3.5 text-neutral-500 dark:text-neutral-400">{formatDate(review.created_at)}</td>
                        <td className="px-5 py-3.5 text-right">
                          <div className="flex items-center justify-end space-x-1.5">
                            <button
                              onClick={() => setExpandedReviewId(expandedReviewId === review.id ? null : review.id)}
                              className="p-1.5 text-neutral-400 hover:text-brand-amber transition-colors"
                              title="Toggle Details"
                            >
                              <ChevronDown className={cn("w-4 h-4 transition-transform", expandedReviewId === review.id && "rotate-180")} />
                            </button>
                            {review.status !== 'approved' && (
                              <button
                                onClick={() => handleUpdateStatus(review.id, 'approved')}
                                className="p-1.5 text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-950/30 rounded transition-colors"
                                title="Approve"
                              >
                                <Check className="w-3.5 h-3.5" />
                              </button>
                            )}
                            {review.status !== 'rejected' && (
                              <button
                                onClick={() => handleUpdateStatus(review.id, 'rejected')}
                                className="p-1.5 text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-950/30 rounded transition-colors"
                                title="Reject"
                              >
                                <X className="w-3.5 h-3.5" />
                              </button>
                            )}
                            <button
                              onClick={() => handleDelete(review.id)}
                              className="p-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-950/30 rounded transition-colors"
                              title="Delete"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        </td>
                      </tr>
                      {expandedReviewId === review.id && (
                        <tr>
                          <td colSpan={7} className="px-6 py-4 bg-neutral-50/50 dark:bg-neutral-900/40 border-b border-neutral-100 dark:border-neutral-800 whitespace-normal">
                            <div className="pl-10">
                              <h4 className="font-semibold text-neutral-900 dark:text-neutral-100 mb-1 text-sm">{review.title}</h4>
                              <p className="text-neutral-600 dark:text-neutral-400 text-xs max-w-3xl leading-relaxed">{review.comment}</p>
                              {review.images && review.images.length > 0 && (
                                <div className="flex space-x-2 mt-3">
                                  {review.images.map((img, idx) => (
                                    <img key={idx} src={img} alt="" className="w-16 h-16 object-cover rounded-lg border border-neutral-200 dark:border-neutral-700" />
                                  ))}
                                </div>
                              )}
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';
import { useState, useEffect } from 'react';
import { DataStore } from '@/lib/store/data-store';
import { useStore } from '@/lib/context/StoreContext';
import { Save, ShieldAlert, ShoppingBag, BarChart3, Building2, CreditCard, Truck, Receipt, Sparkles, CheckCircle2, Mail, Send, AlertCircle, Loader2 } from 'lucide-react';
import type { StoreSettings } from '@/types';
import { cn } from '@/lib/utils';

export default function StoreSettingsAdminPage() {
  const { settings, refreshData } = useStore();
  const [formData, setFormData] = useState<StoreSettings | null>(null);
  const [activeTab, setActiveTab] = useState('General');
  const [savedSuccess, setSavedSuccess] = useState(false);
  const [testEmailRecipient, setTestEmailRecipient] = useState('mdkaif84000@gmail.com');
  const [testEmailStatus, setTestEmailStatus] = useState<{ loading: boolean; success?: boolean; message?: string }>({ loading: false });

  useEffect(() => {
    if (settings) {
      // Ensure new subsections have safe default objects
      setFormData({
        ...settings,
        business: settings.business || {
          legalName: '',
          tradeName: 'Ozeira Atelier',
          gstin: '',
          pan: '',
          registeredAddress: '',
          supportEmail: 'care@ozeira.com',
          supportPhone: '+91 98765 43210',
        },
        abandonedCart: settings.abandonedCart || {
          isEnabled: true,
          firstDelayHours: 1,
          secondDelayHours: 24,
          reminderCouponCode: 'WELCOME10',
          maxReminders: 2,
          emailSubject: 'Your curated pieces are waiting at Ozeira',
        },
        codFraud: settings.codFraud || {
          requireOtp: true,
          maxCodAmount: 5000,
          blockedPincodes: [],
          blockedPhones: [],
        },
        analytics: settings.analytics || {
          isEnabled: false,
          ga4MeasurementId: '',
          metaPixelId: '',
        },
        email: settings.email || {
          provider: 'gmail',
          smtpHost: 'smtp.gmail.com',
          smtpPort: 465,
          smtpUser: '',
          smtpPass: '',
          resendApiKey: '',
          fromEmail: 'care@ozeira.com',
          fromName: 'Ozeira Atelier',
        },
      });
    }
  }, [settings]);

  if (!formData) return <div className="p-8 text-stone-500">Loading settings...</div>;

  const handleSave = () => {
    DataStore.saveSettings(formData);
    refreshData();
    setSavedSuccess(true);
    setTimeout(() => setSavedSuccess(false), 3000);
  };

  const handleSendTestEmail = async () => {
    if (!testEmailRecipient || !testEmailRecipient.includes('@')) {
      setTestEmailStatus({ loading: false, success: false, message: 'Please enter a valid recipient email.' });
      return;
    }

    setTestEmailStatus({ loading: true });
    try {
      // First save current form data so API reads latest credentials
      DataStore.saveSettings(formData);

      const res = await fetch('/api/send-email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          to: testEmailRecipient.trim(),
          subject: '✨ Ozeira Atelier - Live Email Dispatch Test',
          html: `
            <div style="font-family: Georgia, serif; padding: 24px; background: #fdfbf9; border: 1px solid #e7e5e4; border-radius: 12px; color: #1c1917;">
              <h2 style="color: #c46331; margin-top: 0;">OZEIRA ATELIER</h2>
              <p>This is a live test notification from your Ozeira luxury boutique.</p>
              <p>Your SMTP / Email dispatch pipeline is operating successfully!</p>
              <hr style="border: none; border-top: 1px solid #e7e5e4; margin: 16px 0;" />
              <p style="font-size: 11px; color: #78716c;">Ozeira Atelier • Haute Craftsmanship</p>
            </div>
          `,
          text: 'This is a test notification from Ozeira Atelier. Your SMTP pipeline is operating successfully!',
          is_test: true,
        }),
      });

      const data = await res.json();
      if (res.ok && data.success && !data.simulated) {
        setTestEmailStatus({ loading: false, success: true, message: `✅ Live email successfully delivered to ${testEmailRecipient} via ${data.provider?.toUpperCase()}!` });
      } else if (data.simulated) {
        setTestEmailStatus({ loading: false, success: false, message: `⚠️ SMTP credentials are empty or not configured. Please fill in your SMTP Password (or Gmail App Password) and click Save.` });
      } else {
        setTestEmailStatus({ loading: false, success: false, message: `❌ Dispatch failed: ${data.error || 'Connection rejected'}` });
      }
    } catch (err: any) {
      setTestEmailStatus({ loading: false, success: false, message: `❌ Network error: ${err.message}` });
    }
  };

  const tabs = [
    { id: 'General', label: 'General', icon: Building2 },
    { id: 'Email', label: 'Email & SMTP', icon: Mail },
    { id: 'Business', label: 'Business & GST', icon: Receipt },
    { id: 'COD', label: 'COD & Fraud Rules', icon: ShieldAlert },
    { id: 'AbandonedCart', label: 'Abandoned Cart', icon: ShoppingBag },
    { id: 'Analytics', label: 'Analytics & Tracking', icon: BarChart3 },
    { id: 'Shipping', label: 'Shipping Rates', icon: Truck },
    { id: 'Tax', label: 'Taxation', icon: Receipt },
    { id: 'Loyalty', label: 'Loyalty Program', icon: Sparkles },
    { id: 'Payments', label: 'Payments (Razorpay)', icon: CreditCard },
  ];

  return (
    <div className="space-y-6 max-w-5xl">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-serif font-bold text-stone-900 dark:text-stone-100">Store Settings & Configuration</h1>
          <p className="text-xs text-stone-500 dark:text-stone-400 mt-0.5">Manage live business details, fraud prevention, cart recovery, and analytics.</p>
        </div>
        <div className="flex items-center gap-3">
          {savedSuccess && (
            <span className="flex items-center gap-1.5 text-xs font-semibold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/40 px-3 py-1.5 rounded-lg">
              <CheckCircle2 className="w-4 h-4" /> Settings Saved!
            </span>
          )}
          <button 
            onClick={handleSave} 
            className="bg-[#1a1714] dark:bg-amber-600 hover:bg-[#c46331] text-white px-5 py-2.5 rounded-xl flex items-center gap-2 text-xs font-bold uppercase tracking-wider shadow-sm transition-all"
          >
            <Save className="w-4 h-4" /> Save Changes
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-[#14151a] rounded-2xl border border-stone-200 dark:border-stone-800 shadow-sm flex flex-col md:flex-row overflow-hidden">
        {/* Tab Sidebar */}
        <div className="w-full md:w-56 border-b md:border-b-0 md:border-r border-stone-100 dark:border-stone-800 bg-stone-50/50 dark:bg-[#111217] p-3 flex flex-row md:flex-col gap-1 overflow-x-auto">
          {tabs.map((t) => {
            const Icon = t.icon;
            const isSelected = activeTab === t.id;
            return (
              <button
                key={t.id}
                onClick={() => setActiveTab(t.id)}
                className={cn(
                  "flex items-center gap-2.5 text-left px-3.5 py-2.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all",
                  isSelected 
                    ? "bg-[#1a1714] dark:bg-stone-800 text-white shadow-sm" 
                    : "text-stone-600 dark:text-stone-400 hover:bg-stone-100 dark:hover:bg-stone-800/60"
                )}
              >
                <Icon className={cn("w-4 h-4", isSelected ? "text-amber-400" : "text-stone-400")} />
                {t.label}
              </button>
            );
          })}
        </div>

        {/* Tab Content Area */}
        <div className="flex-1 p-6 lg:p-8">
          {/* 1. General Details */}
          {activeTab === 'General' && (
            <div className="space-y-5 animate-fade-in">
              <div className="border-b border-stone-100 dark:border-stone-800 pb-3">
                <h2 className="text-base font-bold text-stone-900 dark:text-stone-100">Store Profile & Branding</h2>
                <p className="text-xs text-stone-500">Public store identity displayed on storefront and order headers.</p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Store Public Name</label>
                  <input 
                    type="text" 
                    className="w-full text-xs border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-900 rounded-xl p-2.5 text-stone-900 dark:text-stone-100" 
                    value={formData.general.storeName} 
                    onChange={e=>setFormData({...formData, general:{...formData.general, storeName: e.target.value}})} 
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Support Concierge Email</label>
                  <input 
                    type="email" 
                    className="w-full text-xs border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-900 rounded-xl p-2.5 text-stone-900 dark:text-stone-100" 
                    value={formData.general.supportEmail} 
                    onChange={e=>setFormData({...formData, general:{...formData.general, supportEmail: e.target.value}})} 
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Support Phone</label>
                  <input 
                    type="text" 
                    className="w-full text-xs border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-900 rounded-xl p-2.5 text-stone-900 dark:text-stone-100" 
                    value={formData.general.supportPhone} 
                    onChange={e=>setFormData({...formData, general:{...formData.general, supportPhone: e.target.value}})} 
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 mb-1.5">WhatsApp Concierge Number</label>
                  <input 
                    type="text" 
                    className="w-full text-xs border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-900 rounded-xl p-2.5 text-stone-900 dark:text-stone-100" 
                    value={formData.general.whatsappNumber} 
                    onChange={e=>setFormData({...formData, general:{...formData.general, whatsappNumber: e.target.value}})} 
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Tagline</label>
                <input 
                  type="text" 
                  className="w-full text-xs border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-900 rounded-xl p-2.5 text-stone-900 dark:text-stone-100" 
                  value={formData.general.tagline} 
                  onChange={e=>setFormData({...formData, general:{...formData.general, tagline: e.target.value}})} 
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Physical Atelier / Showroom Address</label>
                <textarea 
                  className="w-full text-xs border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-900 rounded-xl p-2.5 text-stone-900 dark:text-stone-100" 
                  rows={2} 
                  value={formData.general.supportAddress} 
                  onChange={e=>setFormData({...formData, general:{...formData.general, supportAddress: e.target.value}})} 
                />
              </div>
            </div>
          )}

          {/* Email & SMTP Dispatcher Tab */}
          {activeTab === 'Email' && (
            <div className="space-y-6 animate-fade-in">
              <div className="border-b border-stone-100 dark:border-stone-800 pb-3">
                <h2 className="text-base font-bold text-stone-900 dark:text-stone-100">Live Email & SMTP Dispatcher</h2>
                <p className="text-xs text-stone-500">Configure your email provider to send real order confirmations, cancellation notices, and tracking updates to customers.</p>
              </div>

              {/* Instructions Tip Box */}
              <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-4 text-xs text-amber-900 dark:text-amber-300 space-y-2">
                <div className="font-bold flex items-center gap-1.5">
                  <Sparkles className="w-4 h-4 text-amber-500" />
                  <span>How to setup live customer email dispatch:</span>
                </div>
                <ul className="list-disc pl-4 space-y-1 text-[11px] text-amber-800 dark:text-amber-300/90">
