import { NextResponse } from 'next/server';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { DataStore } from '@/lib/store/data-store';
import { OrderStatus } from '@/types';

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { awb, courier, current_status, event_time, location, order_id, order_number } = body;

    console.log(`🚚 [Courier Webhook] Received tracking update for AWB: ${awb} - Status: ${current_status}`);

    // Map carrier status string to internal OrderStatus
    let targetStatus: OrderStatus | undefined;
    const lowerStatus = (current_status || '').toLowerCase();

    if (lowerStatus.includes('out for delivery') || lowerStatus.includes('out_for_delivery')) {
      targetStatus = 'out_for_delivery';
    } else if (lowerStatus.includes('delivered') || lowerStatus.includes('completed')) {
      targetStatus = 'delivered';
    } else if (lowerStatus.includes('in transit') || lowerStatus.includes('shipped') || lowerStatus.includes('dispatched')) {
      targetStatus = 'shipped';
    }

    if (targetStatus && (order_id || order_number || awb)) {
      // Find matching order
      let targetOrder = DataStore.getOrders().find(
        (o) => o.id === order_id || o.order_number === order_number || o.tracking_number === awb
      );

      if (targetOrder) {
        await DataStore.updateOrderStatus(
          targetOrder.id,
          targetStatus,
          `Carrier update from ${courier || 'Courier'}: ${current_status} at ${location || 'Hub'}`
        );
      }
    }

    return NextResponse.json({
      success: true,
      processed_status: targetStatus || current_status,
    });
  } catch (err: any) {
    console.error('Courier webhook error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { NotificationService } from '@/lib/services/notification-service';

export async function GET(request: Request) {
  try {
    const authHeader = request.headers.get('authorization');
    const cronSecret = process.env.CRON_SECRET;

    if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
      return NextResponse.json({ error: 'Unauthorized cron trigger' }, { status: 401 });
    }

    console.log('⏰ [Abandoned Cart Cron] Running abandoned checkout recovery scanner...');

    let recoveredCount = 0;
    const now = new Date();

    if (isSupabaseConfigured) {
      try {
        // Fetch abandoned carts created in last 7 days that are not recovered and have < 2 reminders
        const { data: carts, error } = await supabase
          .from('abandoned_carts')
          .select('*')
          .eq('is_recovered', false)
          .lt('reminder_count', 2);

        if (carts && carts.length > 0) {
          for (const cart of carts) {
            const createdAt = new Date(cart.created_at);
            const hoursSince = (now.getTime() - createdAt.getTime()) / (1000 * 60 * 60);

            // 1st Reminder (After 1 hour)
            if (hoursSince >= 1 && cart.reminder_count === 0 && cart.email) {
              await sendRecoveryEmail(cart, 1);
              await supabase
                .from('abandoned_carts')
                .update({ reminder_count: 1, last_reminded_at: now.toISOString() })
                .eq('id', cart.id);
              recoveredCount++;
            }
            // 2nd Reminder with Voucher (After 24 hours)
            else if (hoursSince >= 24 && cart.reminder_count === 1 && cart.email) {
              await sendRecoveryEmail(cart, 2);
              await supabase
                .from('abandoned_carts')
                .update({ reminder_count: 2, last_reminded_at: now.toISOString() })
                .eq('id', cart.id);
              recoveredCount++;
            }
          }
        }
      } catch (dbErr) {
        console.warn('Abandoned cart table scan notice:', dbErr);
      }
    }

    return NextResponse.json({
      success: true,
      scanned_at: now.toISOString(),
      recovered_reminders_dispatched: recoveredCount,
      message: `Abandoned cart scan complete. Dispatched ${recoveredCount} reminder(s).`,
    });
  } catch (err: any) {
    console.error('Abandoned cart cron error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

