import { NextResponse } from 'next/server';
import crypto from 'crypto';
import { DataStore } from '@/lib/store/data-store';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { amount, currency = 'INR', receipt, notes } = body;

    if (!amount || amount <= 0) {
      return NextResponse.json({ error: 'Invalid order amount' }, { status: 400 });
    }

    // Amount in paise
    const amountInPaise = Math.round(amount * 100);

    // Fetch Razorpay credentials from env or store_settings
    let keyId = process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || 'rzp_test_ozeira_key';
    let keySecret = process.env.RAZORPAY_KEY_SECRET;

    if (isSupabaseConfigured && !keySecret) {
      try {
        const { data: settsData } = await supabase
          .from('store_settings')
          .select('value')
          .eq('key', 'global_settings')
          .single();
        if (settsData?.value?.payments) {
          keyId = settsData.value.payments.razorpayKeyId || keyId;
          keySecret = settsData.value.payments.razorpayKeySecret || keySecret;
        }
      } catch (e) {
        console.warn('Could not load payment settings for Razorpay:', e);
      }
    }

    // If real keySecret exists, invoke real Razorpay REST API
    if (keySecret && keyId && !keyId.includes('rzp_test_ozeira_key')) {
      const authHeader = Buffer.from(`${keyId}:${keySecret}`).toString('base64');
      const res = await fetch('https://api.razorpay.com/v1/orders', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Basic ${authHeader}`,
        },
        body: JSON.stringify({
          amount: amountInPaise,
          currency,
          receipt: receipt || `rec_${Date.now()}`,
          notes: notes || {},
        }),
      });

      const razorpayOrder = await res.json();
      if (!res.ok) {
        console.error('Razorpay API error:', razorpayOrder);
        return NextResponse.json({ error: razorpayOrder.error?.description || 'Razorpay order creation failed' }, { status: 500 });
      }

      return NextResponse.json({
        success: true,
        order_id: razorpayOrder.id,
        amount: razorpayOrder.amount,
        currency: razorpayOrder.currency,
        key_id: keyId,
      });
    }

    // Fallback: Test Mode secure order reference
    const simulatedOrderId = `order_${crypto.randomBytes(10).toString('hex')}`;
    return NextResponse.json({
      success: true,
      order_id: simulatedOrderId,
      amount: amountInPaise,
      currency,
      key_id: keyId,
      simulated: true,
    });
  } catch (err: any) {
    console.error('Razorpay create order API error:', err);
    return NextResponse.json({ error: err?.message || 'Server error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import crypto from 'crypto';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { DataStore } from '@/lib/store/data-store';

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature, order_id } = body;

    if (!razorpay_order_id || !razorpay_payment_id) {
      return NextResponse.json({ error: 'Missing required payment verification parameters' }, { status: 400 });
    }

    let keySecret = process.env.RAZORPAY_KEY_SECRET;

    if (isSupabaseConfigured && !keySecret) {
      try {
        const { data: settsData } = await supabase
          .from('store_settings')
          .select('value')
          .eq('key', 'global_settings')
          .single();
        if (settsData?.value?.payments) {
          keySecret = settsData.value.payments.razorpayKeySecret || keySecret;
        }
      } catch (e) {
        console.warn('Could not load payment settings for verification:', e);
      }
    }

    // Cryptographic HMAC SHA256 Signature Verification
    let isValid = false;

    if (keySecret) {
      const generatedSignature = crypto
        .createHmac('sha256', keySecret)
        .update(`${razorpay_order_id}|${razorpay_payment_id}`)
        .digest('hex');

      isValid = generatedSignature === razorpay_signature;
    } else {
      // Test Mode validation
      isValid = true;
    }

    if (!isValid) {
      return NextResponse.json({ success: false, error: 'Payment signature verification failed. Potential tampering detected.' }, { status: 400 });
    }

    // Update order status in Supabase and local store
    if (order_id) {
      if (isSupabaseConfigured) {
        try {
          await supabase
            .from('orders')
            .update({
              payment_status: 'paid',
              razorpay_payment_id,
              razorpay_order_id,
              status: 'confirmed',
            })
            .eq('id', order_id);
        } catch (dbErr) {
          console.error('Error updating order payment status in Supabase:', dbErr);
        }
      }
    }

    return NextResponse.json({
      success: true,
      verified: true,
      message: 'Razorpay payment signature verified successfully.',
    });
  } catch (err: any) {
    console.error('Payment verification error:', err);
    return NextResponse.json({ error: err?.message || 'Verification failed' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import crypto from 'crypto';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { DataStore } from '@/lib/store/data-store';

export async function POST(request: Request) {
  try {
    const rawBody = await request.text();
    const signature = request.headers.get('x-razorpay-signature');
    const webhookSecret = process.env.RAZORPAY_WEBHOOK_SECRET;

    // Validate webhook secret if configured
    if (webhookSecret && signature) {
      const expectedSignature = crypto
        .createHmac('sha256', webhookSecret)
        .update(rawBody)
        .digest('hex');

      if (expectedSignature !== signature) {
        return NextResponse.json({ error: 'Invalid webhook signature' }, { status: 400 });
      }
    }

    const payload = JSON.parse(rawBody);
    const event = payload.event;
    console.log(`💳 [Razorpay Webhook] Received event: ${event}`);

    if (event === 'payment.captured' || event === 'order.paid') {
      const payment = payload.payload?.payment?.entity;
      const orderId = payment?.order_id;
      const amount = payment?.amount ? payment.amount / 100 : 0;

      if (isSupabaseConfigured && orderId) {
        await supabase
          .from('orders')
          .update({
            payment_status: 'paid',
            razorpay_payment_id: payment.id,
            status: 'confirmed',
          })
          .eq('razorpay_order_id', orderId);
      }
    } else if (event === 'payment.failed') {
      const payment = payload.payload?.payment?.entity;
      const orderId = payment?.order_id;

      if (isSupabaseConfigured && orderId) {
        await supabase
          .from('orders')
          .update({
            payment_status: 'failed',
          })
          .eq('razorpay_order_id', orderId);
      }
    }

    return NextResponse.json({ received: true });
  } catch (err: any) {
    console.error('Razorpay Webhook error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

